      { type: 'line', title: 'U.S. Unemployment Rate: 2019-2024', points: [{ label: '2019', value: '3.5%' }, { label: 'Apr 2020', value: '14.7%' }, { label: '2023', value: '3.4%' }], trend: 'down', sentiment: 'positive' }
