        { term: 'Debt-to-GDP Ratio', definition: 'National debt divided by GDP. The key metric for debt sustainability, shows debt relative to the economy\'s ability to service it.', example: 'U.S.: 123%. Japan: 264%. Germany: 64%. A high ratio isn\'t automatically dangerous, Japan has 264% but borrows at near-zero rates.' },
        { term: 'Sovereign Default', definition: 'When a government fails to make payments on its debt. Rare for advanced economies but devastating for developing ones.', example: 'Argentina defaulted in 2001 ($100B, then the largest default in history), 2014, and 2020. Greece restructured in 2012. Sri Lanka defaulted in 2022.' },
        { term: 'Fiscal Space', definition: 'A government\'s capacity to borrow and spend without triggering a debt crisis. Determined by debt-to-GDP, interest costs, growth rate, and investor confidence.', example: 'Germany (64% debt-to-GDP) has large fiscal space. Sri Lanka (before default) had none, interest payments consumed 70% of revenue.' }
