        withVisual: { type: 'flow', title: 'Integrated', nodes: [{ label: 'Synthesized' }, { label: 'Multi-Frame' }, { label: 'Connects all frameworks' }, { label: 'Handles complexity with clarity' }, { label: 'Thinks like a professional' }], sentiment: 'positive' }
